import requests
import json

url = "https://partner.shopeemobile.com/api/v2/discount/set_sip_discount?access_token=access_token&partner_id=partner_id&shop_id=shop_id&sign=sign&timestamp=timestamp"

payload=json.dumps({
  "region": "TH",
  "sip_discount_rate": 15
})
headers = {
  'Content-Type': 'application/json'
}
response = requests.RPCRequest("POST",url,headers=headers, data=payload, allow_redirects=False)

print(response.text)

